    local into
    if v.merge then
        for _, o in ipairs(vendors) do if o.kind == v.kind and o.faction == v.faction then into = o; break end end
    end
    if into then
        for _, e in ipairs(v.items) do into.items[#into.items + 1] = e end
    else
        v.merge = nil
        vendors[#vendors + 1] = v
    end
end
